def get_expanded_v3_rosetta():
    """Return all v3 expanded handcrafted entries."""
    entries = []
    idx = 30000
    for concept, lang_codes in EXPANDED_V3.items():
        cn = concept.replace('_', ' ').title()
        for lang, code in lang_codes.items():
            idx += 1
            entries.append({
                "id": f"rosetta_v3_{idx}",
                "concept": concept,
                "concept_name": cn,
                "language": lang,
                "code": code,
                "category": "rosetta_stone",
                "has_code": True,
                "code_lines": len(code.split('\n')),
                "source": "handcrafted",
            })
    return entries
